import{_ as e,o as l,c as r,a3 as a}from"./chunks/framework.BHpftTUY.js";const y=JSON.parse('{"title":"RFC support","description":"The RFCs yarilo implements, by service: IMAP, POP3, Submission, LMTP, JMAP, Sieve and ManageSieve, authentication, message format, the policy server and client autoconfiguration, each with its state.","frontmatter":{"description":"The RFCs yarilo implements, by service: IMAP, POP3, Submission, LMTP, JMAP, Sieve and ManageSieve, authentication, message format, the policy server and client autoconfiguration, each with its state.","head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/reference/rfcs.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/2.4.5/reference/rfcs.html"}],["meta",{"property":"og:title","content":"RFC support"}],["meta",{"name":"twitter:title","content":"RFC support"}],["meta",{"property":"og:description","content":"The RFCs yarilo implements, by service: IMAP, POP3, Submission, LMTP, JMAP, Sieve and ManageSieve, authentication, message format, the policy server and client autoconfiguration, each with its state."}],["meta",{"name":"twitter:description","content":"The RFCs yarilo implements, by service: IMAP, POP3, Submission, LMTP, JMAP, Sieve and ManageSieve, authentication, message format, the policy server and client autoconfiguration, each with its state."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/2.4.5/reference/rfcs.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/2.4.5/reference/rfcs.html\\",\\"headline\\":\\"RFC support\\",\\"description\\":\\"The RFCs yarilo implements, by service: IMAP, POP3, Submission, LMTP, JMAP, Sieve and ManageSieve, authentication, message format, the policy server and client autoconfiguration, each with its state.\\",\\"dateModified\\":\\"2026-10-30T22:54:22.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"RFC support\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/reference/rfcs.html\\"}]}]}"]]},"headers":[],"relativePath":"reference/rfcs.md","filePath":"reference/rfcs.md","lastUpdated":1793400862000}'),d={name:"reference/rfcs.md"};function o(n,t,f,s,i,c){return l(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="rfc-support" tabindex="-1">RFC support <a class="header-anchor" href="#rfc-support" aria-label="Permalink to &quot;RFC support&quot;">​</a></h1><p>The standards each yarilo service implements, and how far. A row is <strong>yes</strong> only when the code serves it and, for an extension a client discovers, the server advertises it: a command a client is never told about is, to that client, absent.</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>yes</strong></td><td style="text-align:left;">implemented and advertised where the protocol advertises</td></tr><tr><td style="text-align:left;"><strong>partial</strong></td><td style="text-align:left;">usable with the limit given in the note</td></tr><tr><td style="text-align:left;"><strong>no</strong></td><td style="text-align:left;">not implemented; listed because clients or other servers commonly use it</td></tr></tbody></table><p>Drafts and vendor protocols that yarilo also speaks are listed at the end of each section, without a number. <a href="/2.4.5/architecture/parity.html">Feature coverage</a> is the same picture by feature rather than by standard.</p><h2 id="imap" tabindex="-1">IMAP <a class="header-anchor" href="#imap" aria-label="Permalink to &quot;IMAP&quot;">​</a></h2><p>Served by <code>yarilo-imap</code>, through <code>yarilo-imap-login</code>. Extensions marked <em>after login</em> are in <code>CAPABILITY</code> once the client is authenticated.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9051" target="_blank" rel="noreferrer nofollow">9051</a></td><td style="text-align:left;">IMAP4rev2</td><td style="text-align:left;">yes</td><td style="text-align:left;">after <code>ENABLE IMAP4rev2</code>, no <code>RECENT</code> response and no <code>\\Recent</code> flag; see <a href="/2.4.5/protocols/imap.html#recent-messages">Recent messages</a></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3501" target="_blank" rel="noreferrer nofollow">3501</a></td><td style="text-align:left;">IMAP4rev1</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>\\Recent</code> held by the first session that selects the folder; see <a href="/2.4.5/protocols/imap.html#recent-messages">Recent messages</a></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2180" target="_blank" rel="noreferrer nofollow">2180</a></td><td style="text-align:left;">IMAP4 multi-accessed mailbox practice</td><td style="text-align:left;">partial</td><td style="text-align:left;">a <code>COPY</code> that meets a message another session expunged copies nothing and answers <code>NO [EXPUNGEISSUED]</code> (§4.4.1)</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2177" target="_blank" rel="noreferrer nofollow">2177</a></td><td style="text-align:left;">IDLE</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2342" target="_blank" rel="noreferrer nofollow">2342</a></td><td style="text-align:left;">NAMESPACE</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login; see <a href="/2.4.5/storage/namespace.html">Namespaces</a></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2971" target="_blank" rel="noreferrer nofollow">2971</a></td><td style="text-align:left;">ID</td><td style="text-align:left;">yes</td><td style="text-align:left;">before login always; after login while <code>imap_<wbr>id_<wbr>send</code> is non-empty; with <code>imap_<wbr>id_<wbr>retain</code>, the client&#39;s <code>ID</code> goes to the <a href="/2.4.5/auth/policy.html">policy server</a> as <code>device_<wbr>id</code></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3516" target="_blank" rel="noreferrer nofollow">3516</a></td><td style="text-align:left;">BINARY</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3691" target="_blank" rel="noreferrer nofollow">3691</a></td><td style="text-align:left;">UNSELECT</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4314" target="_blank" rel="noreferrer nofollow">4314</a></td><td style="text-align:left;">ACL</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login, with <code>acl.<wbr>enabled</code> (off by default); <code>SELECT</code> answers <code>[READ-ONLY]</code> without any of <code>i</code>, <code>e</code>, <code>w</code>, <code>t</code>, <code>s</code></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4315" target="_blank" rel="noreferrer nofollow">4315</a></td><td style="text-align:left;">UIDPLUS</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4731" target="_blank" rel="noreferrer nofollow">4731</a></td><td style="text-align:left;">ESEARCH</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4959" target="_blank" rel="noreferrer nofollow">4959</a></td><td style="text-align:left;">SASL-IR</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5161" target="_blank" rel="noreferrer nofollow">5161</a></td><td style="text-align:left;">ENABLE</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5182" target="_blank" rel="noreferrer nofollow">5182</a></td><td style="text-align:left;">SEARCHRES</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5256" target="_blank" rel="noreferrer nofollow">5256</a></td><td style="text-align:left;">SORT, THREAD</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login: <code>SORT</code>, <code>THREAD=REFERENCES</code>, <code>THREAD=ORDEREDSUBJECT</code></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5258" target="_blank" rel="noreferrer nofollow">5258</a></td><td style="text-align:left;">LIST-EXTENDED</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5464" target="_blank" rel="noreferrer nofollow">5464</a></td><td style="text-align:left;">METADATA</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login, when a <code>metadata</code> dict is configured</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5465" target="_blank" rel="noreferrer nofollow">5465</a></td><td style="text-align:left;">NOTIFY</td><td style="text-align:left;">partial</td><td style="text-align:left;">after login; annotation and metadata events are not reported</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5530" target="_blank" rel="noreferrer nofollow">5530</a></td><td style="text-align:left;">IMAP response codes</td><td style="text-align:left;">partial</td><td style="text-align:left;">sent: <code>AUTHENTICATIONFAILED</code>, <code>CANNOT</code>, <code>CLIENTBUG</code>, <code>CORRUPTION</code>, <code>EXPUNGEISSUED</code>, <code>LIMIT</code>, <code>NONEXISTENT</code>, <code>NOPERM</code>, <code>OVERQUOTA</code>, <code>SERVERBUG</code>, <code>UNAVAILABLE</code>; the others are not</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5819" target="_blank" rel="noreferrer nofollow">5819</a></td><td style="text-align:left;">LIST-STATUS</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6154" target="_blank" rel="noreferrer nofollow">6154</a></td><td style="text-align:left;">SPECIAL-USE, CREATE-SPECIAL-USE</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6851" target="_blank" rel="noreferrer nofollow">6851</a></td><td style="text-align:left;">MOVE</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6855" target="_blank" rel="noreferrer nofollow">6855</a></td><td style="text-align:left;">UTF8=ACCEPT</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7162" target="_blank" rel="noreferrer nofollow">7162</a></td><td style="text-align:left;">CONDSTORE, QRESYNC</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7888" target="_blank" rel="noreferrer nofollow">7888</a></td><td style="text-align:left;">LITERAL+</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8438" target="_blank" rel="noreferrer nofollow">8438</a></td><td style="text-align:left;">STATUS=SIZE</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8474" target="_blank" rel="noreferrer nofollow">8474</a></td><td style="text-align:left;">OBJECTID</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login: <code>MAILBOXID</code>, <code>EMAILID</code>, <code>THREADID</code></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9208" target="_blank" rel="noreferrer nofollow">9208</a></td><td style="text-align:left;">QUOTA</td><td style="text-align:left;">yes</td><td style="text-align:left;">after login, while <code>imap_<wbr>quota</code> is on (the default)</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3348" target="_blank" rel="noreferrer nofollow">3348</a></td><td style="text-align:left;">CHILDREN</td><td style="text-align:left;">no</td><td style="text-align:left;">not advertised</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3502" target="_blank" rel="noreferrer nofollow">3502</a></td><td style="text-align:left;">MULTIAPPEND</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4467" target="_blank" rel="noreferrer nofollow">4467</a></td><td style="text-align:left;">URLAUTH</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4469" target="_blank" rel="noreferrer nofollow">4469</a></td><td style="text-align:left;">CATENATE</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4978" target="_blank" rel="noreferrer nofollow">4978</a></td><td style="text-align:left;">COMPRESS=DEFLATE</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5255" target="_blank" rel="noreferrer nofollow">5255</a></td><td style="text-align:left;">I18NLEVEL</td><td style="text-align:left;">no</td><td style="text-align:left;">SORT and THREAD collate with <code>i;unicode-casemap</code>, but the extension is not advertised</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5267" target="_blank" rel="noreferrer nofollow">5267</a></td><td style="text-align:left;">ESORT, CONTEXT=SEARCH, CONTEXT=SORT</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5957" target="_blank" rel="noreferrer nofollow">5957</a></td><td style="text-align:left;">SORT=DISPLAY</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7889" target="_blank" rel="noreferrer nofollow">7889</a></td><td style="text-align:left;">APPENDLIMIT</td><td style="text-align:left;">no</td><td style="text-align:left;">not advertised; the size limit still applies</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8437" target="_blank" rel="noreferrer nofollow">8437</a></td><td style="text-align:left;">UNAUTHENTICATE</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8508" target="_blank" rel="noreferrer nofollow">8508</a></td><td style="text-align:left;">REPLACE</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8514" target="_blank" rel="noreferrer nofollow">8514</a></td><td style="text-align:left;">SAVEDATE</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8970" target="_blank" rel="noreferrer nofollow">8970</a></td><td style="text-align:left;">PREVIEW</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr></tbody></table><p>See <a href="/2.4.5/protocols/imap.html">IMAP</a> for the settings.</p><h2 id="pop3" tabindex="-1">POP3 <a class="header-anchor" href="#pop3" aria-label="Permalink to &quot;POP3&quot;">​</a></h2><p>Served by <code>yarilo-pop3</code>, through <code>yarilo-pop3-login</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc1939" target="_blank" rel="noreferrer nofollow">1939</a></td><td style="text-align:left;">POP3</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2449" target="_blank" rel="noreferrer nofollow">2449</a></td><td style="text-align:left;">Extension mechanism</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>CAPA</code> with <code>TOP</code>, <code>UIDL</code>, <code>USER</code>, <code>RESP-CODES</code>, <code>PIPELINING</code>; <code>EXPIRE</code> and <code>LOGIN-DELAY</code> are not advertised</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2595" target="_blank" rel="noreferrer nofollow">2595</a></td><td style="text-align:left;">STLS</td><td style="text-align:left;">yes</td><td style="text-align:left;">on a listener with STARTTLS</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3206" target="_blank" rel="noreferrer nofollow">3206</a></td><td style="text-align:left;">SYS and AUTH response codes</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>AUTH-RESP-CODE</code></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5034" target="_blank" rel="noreferrer nofollow">5034</a></td><td style="text-align:left;">SASL authentication</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc1460" target="_blank" rel="noreferrer nofollow">1460</a></td><td style="text-align:left;"><code>LAST</code></td><td style="text-align:left;">yes</td><td style="text-align:left;">with <code>pop3_<wbr>enable_<wbr>last</code>; the command was dropped from POP3 by RFC 1725</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6856" target="_blank" rel="noreferrer nofollow">6856</a></td><td style="text-align:left;">UTF8</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr></tbody></table><p>See <a href="/2.4.5/protocols/pop3.html">POP3</a>.</p><h2 id="submission" tabindex="-1">Submission <a class="header-anchor" href="#submission" aria-label="Permalink to &quot;Submission&quot;">​</a></h2><p>Served by <code>yarilo-submission</code>, through <code>yarilo-submission-login</code>, which answers <code>EHLO</code> until the client has authenticated. The client keeps that answer for the session, so it lists the extensions <code>yarilo-submission</code> serves, with the same limits.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5321" target="_blank" rel="noreferrer nofollow">5321</a></td><td style="text-align:left;">SMTP</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6409" target="_blank" rel="noreferrer nofollow">6409</a></td><td style="text-align:left;">Message submission</td><td style="text-align:left;">yes</td><td style="text-align:left;">relayed to an external MTA</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3207" target="_blank" rel="noreferrer nofollow">3207</a></td><td style="text-align:left;">STARTTLS</td><td style="text-align:left;">yes</td><td style="text-align:left;">port 587</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8314" target="_blank" rel="noreferrer nofollow">8314</a></td><td style="text-align:left;">Implicit TLS</td><td style="text-align:left;">yes</td><td style="text-align:left;">port 465</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4954" target="_blank" rel="noreferrer nofollow">4954</a></td><td style="text-align:left;">AUTH</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6152" target="_blank" rel="noreferrer nofollow">6152</a></td><td style="text-align:left;">8BITMIME</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc1870" target="_blank" rel="noreferrer nofollow">1870</a></td><td style="text-align:left;">SIZE</td><td style="text-align:left;">yes</td><td style="text-align:left;">the <code>submission_<wbr>max_<wbr>mail_<wbr>size</code> limit</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2920" target="_blank" rel="noreferrer nofollow">2920</a></td><td style="text-align:left;">PIPELINING</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2034" target="_blank" rel="noreferrer nofollow">2034</a></td><td style="text-align:left;">ENHANCEDSTATUSCODES</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3030" target="_blank" rel="noreferrer nofollow">3030</a></td><td style="text-align:left;">CHUNKING</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9422" target="_blank" rel="noreferrer nofollow">9422</a></td><td style="text-align:left;">LIMITS</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>RCPTMAX</code> when <code>submission_<wbr>max_<wbr>recipients</code> is set</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3461" target="_blank" rel="noreferrer nofollow">3461</a></td><td style="text-align:left;">DSN</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3030" target="_blank" rel="noreferrer nofollow">3030</a></td><td style="text-align:left;">BINARYMIME</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4468" target="_blank" rel="noreferrer nofollow">4468</a></td><td style="text-align:left;">BURL</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6531" target="_blank" rel="noreferrer nofollow">6531</a></td><td style="text-align:left;">SMTPUTF8</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8689" target="_blank" rel="noreferrer nofollow">8689</a></td><td style="text-align:left;">REQUIRETLS</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr></tbody></table><p>Also spoken: <code>XCLIENT</code> (Postfix), toward a relay that advertises it and from peers in <code>general.<wbr>xclient.<wbr>trusted_<wbr>nets</code>. See <a href="/2.4.5/protocols/submission.html">Submission</a>.</p><h2 id="lmtp" tabindex="-1">LMTP <a class="header-anchor" href="#lmtp" aria-label="Permalink to &quot;LMTP&quot;">​</a></h2><p>Served by <code>yarilo-lmtp</code>, through <code>yarilo-lmtp-login</code>, which answers <code>LHLO</code> itself.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2033" target="_blank" rel="noreferrer nofollow">2033</a></td><td style="text-align:left;">LMTP</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6152" target="_blank" rel="noreferrer nofollow">6152</a></td><td style="text-align:left;">8BITMIME</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc1870" target="_blank" rel="noreferrer nofollow">1870</a></td><td style="text-align:left;">SIZE</td><td style="text-align:left;">yes</td><td style="text-align:left;">the <code>quota_<wbr>mail_<wbr>size</code> limit when set</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2920" target="_blank" rel="noreferrer nofollow">2920</a></td><td style="text-align:left;">PIPELINING</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2034" target="_blank" rel="noreferrer nofollow">2034</a></td><td style="text-align:left;">ENHANCEDSTATUSCODES</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3030" target="_blank" rel="noreferrer nofollow">3030</a></td><td style="text-align:left;">CHUNKING</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9422" target="_blank" rel="noreferrer nofollow">9422</a></td><td style="text-align:left;">LIMITS</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>RCPTMAX</code> when <code>lmtp_<wbr>max_<wbr>recipients</code> is set</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3461" target="_blank" rel="noreferrer nofollow">3461</a></td><td style="text-align:left;">DSN</td><td style="text-align:left;">partial</td><td style="text-align:left;"><code>ORCPT</code> is accepted; <code>DSN</code> is not advertised</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6531" target="_blank" rel="noreferrer nofollow">6531</a></td><td style="text-align:left;">SMTPUTF8</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr></tbody></table><p>Also spoken: <code>XCLIENT</code> (Postfix), from peers in <code>general.<wbr>xclient.<wbr>trusted_<wbr>nets</code>. See <a href="/2.4.5/protocols/lmtp.html">LMTP</a>.</p><h2 id="jmap" tabindex="-1">JMAP <a class="header-anchor" href="#jmap" aria-label="Permalink to &quot;JMAP&quot;">​</a></h2><p>Served by <code>yarilo-jmap</code>, through <code>yarilo-jmap-login</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8620" target="_blank" rel="noreferrer nofollow">8620</a></td><td style="text-align:left;">JMAP core</td><td style="text-align:left;">yes</td><td style="text-align:left;">session, request envelope, back-references, blob upload and download</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8620#section-7.3" target="_blank" rel="noreferrer nofollow">8620 §7.3</a></td><td style="text-align:left;">Push over EventSource</td><td style="text-align:left;">yes</td><td style="text-align:left;">a write on any pod reaches the stream as a <code>yarilo-locks</code> event; off with <code>jmap_<wbr>push_<wbr>poll: 0</code>, see <a href="/2.4.5/protocols/jmap.html#push">Push</a></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8621" target="_blank" rel="noreferrer nofollow">8621</a></td><td style="text-align:left;">JMAP for Mail</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>Mailbox/<wbr>queryChanges</code> and <code>Email/<wbr>queryChanges</code> answer <code>cannotCalculateChanges</code>, which the RFC allows. <code>header:*</code> properties are set on <code>Email/<wbr>set</code> create as §4.6 describes. <code>Email/<wbr>get</code> answers a <code>header:*</code> property in whatever form the client asks for any field; the §4.1.2 refusal is not applied, by decision, because a current web client asks for <code>asText</code> on <code>List-*</code> fields and would show no messages</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8621#section-6" target="_blank" rel="noreferrer nofollow">8621 §6</a></td><td style="text-align:left;">Identities</td><td style="text-align:left;">yes</td><td style="text-align:left;">when a relay is configured; the login&#39;s and the userdb aliases&#39; identities can be changed, not destroyed</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8621#section-7" target="_blank" rel="noreferrer nofollow">8621 §7</a></td><td style="text-align:left;">Submission</td><td style="text-align:left;">yes</td><td style="text-align:left;">when a relay is configured</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8621#section-8" target="_blank" rel="noreferrer nofollow">8621 §8</a></td><td style="text-align:left;">Vacation response</td><td style="text-align:left;">yes</td><td style="text-align:left;">with Sieve vacation on</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9425" target="_blank" rel="noreferrer nofollow">9425</a></td><td style="text-align:left;">JMAP for Quotas</td><td style="text-align:left;">yes</td><td style="text-align:left;">read-only</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9661" target="_blank" rel="noreferrer nofollow">9661</a></td><td style="text-align:left;">JMAP for Sieve scripts</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8620#section-7.2" target="_blank" rel="noreferrer nofollow">8620 §7.2</a></td><td style="text-align:left;">PushSubscription</td><td style="text-align:left;">no</td><td style="text-align:left;">not built until a client needs push while it is offline; an open EventSource or WebSocket gets every change</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8887" target="_blank" rel="noreferrer nofollow">8887</a></td><td style="text-align:left;">JMAP over WebSocket</td><td style="text-align:left;">yes</td><td style="text-align:left;">with push; <code>pushState</code> resumes on any backend; a browser client may open it with a ticket. See <a href="/2.4.5/protocols/jmap.html#websocket">WebSocket</a></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">WebSocket ticket (<code>com:linagora:params:jmap:ws:ticket</code>)</td><td style="text-align:left;">yes</td><td style="text-align:left;">one web client&#39;s own extension: a short-lived ticket instead of credentials on the WebSocket; off with <code>jmap_<wbr>websocket_<wbr>ticket_<wbr>ttl: 0</code>. See <a href="/2.4.5/protocols/jmap.html#tickets-for-browser-clients">Tickets for browser clients</a></td></tr></tbody></table><p>See <a href="/2.4.5/protocols/jmap.html#capabilities">JMAP</a>.</p><h2 id="sieve-and-managesieve" tabindex="-1">Sieve and ManageSieve <a class="header-anchor" href="#sieve-and-managesieve" aria-label="Permalink to &quot;Sieve and ManageSieve&quot;">​</a></h2><p>Scripts run at delivery; <code>sieve_<wbr>extensions</code> narrows the set a deployment offers.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5804" target="_blank" rel="noreferrer nofollow">5804</a></td><td style="text-align:left;">ManageSieve</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5228" target="_blank" rel="noreferrer nofollow">5228</a></td><td style="text-align:left;">Sieve</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>fileinto</code>, <code>reject</code>, <code>envelope</code>, <code>encoded-character</code></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc3894" target="_blank" rel="noreferrer nofollow">3894</a></td><td style="text-align:left;"><code>copy</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5173" target="_blank" rel="noreferrer nofollow">5173</a></td><td style="text-align:left;"><code>body</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5183" target="_blank" rel="noreferrer nofollow">5183</a></td><td style="text-align:left;"><code>environment</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5229" target="_blank" rel="noreferrer nofollow">5229</a></td><td style="text-align:left;"><code>variables</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5230" target="_blank" rel="noreferrer nofollow">5230</a></td><td style="text-align:left;"><code>vacation</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5231" target="_blank" rel="noreferrer nofollow">5231</a></td><td style="text-align:left;"><code>relational</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5232" target="_blank" rel="noreferrer nofollow">5232</a></td><td style="text-align:left;"><code>imap4flags</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5233" target="_blank" rel="noreferrer nofollow">5233</a></td><td style="text-align:left;"><code>subaddress</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5235" target="_blank" rel="noreferrer nofollow">5235</a></td><td style="text-align:left;"><code>spamtest</code>, <code>spamtestplus</code>, <code>virustest</code></td><td style="text-align:left;">yes</td><td style="text-align:left;">report &quot;not scanned&quot; until a status header is configured</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5260" target="_blank" rel="noreferrer nofollow">5260</a></td><td style="text-align:left;"><code>date</code>, <code>index</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5293" target="_blank" rel="noreferrer nofollow">5293</a></td><td style="text-align:left;"><code>editheader</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5429" target="_blank" rel="noreferrer nofollow">5429</a></td><td style="text-align:left;"><code>ereject</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5435" target="_blank" rel="noreferrer nofollow">5435</a></td><td style="text-align:left;"><code>enotify</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5436" target="_blank" rel="noreferrer nofollow">5436</a></td><td style="text-align:left;"><code>mailto</code> notification method</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5463" target="_blank" rel="noreferrer nofollow">5463</a></td><td style="text-align:left;"><code>ihave</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5490" target="_blank" rel="noreferrer nofollow">5490</a></td><td style="text-align:left;"><code>mailbox</code>, <code>mboxmetadata</code>, <code>servermetadata</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5703" target="_blank" rel="noreferrer nofollow">5703</a></td><td style="text-align:left;"><code>foreverypart</code>, <code>mime</code>, <code>extracttext</code>, <code>replace</code>, <code>enclose</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6131" target="_blank" rel="noreferrer nofollow">6131</a></td><td style="text-align:left;"><code>vacation-seconds</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6609" target="_blank" rel="noreferrer nofollow">6609</a></td><td style="text-align:left;"><code>include</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6785" target="_blank" rel="noreferrer nofollow">6785</a></td><td style="text-align:left;">IMAP events (<code>imapsieve</code>)</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7352" target="_blank" rel="noreferrer nofollow">7352</a></td><td style="text-align:left;"><code>duplicate</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8579" target="_blank" rel="noreferrer nofollow">8579</a></td><td style="text-align:left;"><code>special-use</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8580" target="_blank" rel="noreferrer nofollow">8580</a></td><td style="text-align:left;"><code>fcc</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9042" target="_blank" rel="noreferrer nofollow">9042</a></td><td style="text-align:left;"><code>mailboxid</code></td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr></tbody></table><p>Also implemented: <code>regex</code> (draft), and the <code>vnd.<wbr>yarilo.<wbr>*</code> extensions. See <a href="/2.4.5/features/sieve.html">Sieve</a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>SASL mechanisms run in <code>yarilo-auth</code> and are offered by every protocol that authenticates.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4422" target="_blank" rel="noreferrer nofollow">4422</a></td><td style="text-align:left;">SASL</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4616" target="_blank" rel="noreferrer nofollow">4616</a></td><td style="text-align:left;">PLAIN</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5802" target="_blank" rel="noreferrer nofollow">5802</a></td><td style="text-align:left;">SCRAM-SHA-1, SCRAM-SHA-1-PLUS</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7677" target="_blank" rel="noreferrer nofollow">7677</a></td><td style="text-align:left;">SCRAM-SHA-256, SCRAM-SHA-256-PLUS</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9266" target="_blank" rel="noreferrer nofollow">9266</a></td><td style="text-align:left;"><code>tls-exporter</code> channel binding</td><td style="text-align:left;">yes</td><td style="text-align:left;">the <code>-PLUS</code> mechanisms, over TLS 1.3</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7628" target="_blank" rel="noreferrer nofollow">7628</a></td><td style="text-align:left;">OAUTHBEARER</td><td style="text-align:left;">yes</td><td style="text-align:left;">with an OAuth2 passdb</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7662" target="_blank" rel="noreferrer nofollow">7662</a></td><td style="text-align:left;">Token introspection</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7519" target="_blank" rel="noreferrer nofollow">7519</a></td><td style="text-align:left;">JWT</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>local</code> mode</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6749" target="_blank" rel="noreferrer nofollow">6749</a></td><td style="text-align:left;">OAuth 2.0 password grant</td><td style="text-align:left;">yes</td><td style="text-align:left;">for PLAIN and LOGIN, with <code>oauth2_<wbr>grant_<wbr>url</code></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2195" target="_blank" rel="noreferrer nofollow">2195</a></td><td style="text-align:left;">CRAM-MD5</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2831" target="_blank" rel="noreferrer nofollow">2831</a></td><td style="text-align:left;">DIGEST-MD5</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4752" target="_blank" rel="noreferrer nofollow">4752</a></td><td style="text-align:left;">GSSAPI (Kerberos)</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4422#appendix-A" target="_blank" rel="noreferrer nofollow">4422 App. A</a></td><td style="text-align:left;">EXTERNAL</td><td style="text-align:left;">no</td><td style="text-align:left;"></td></tr></tbody></table><p>Also implemented: <code>LOGIN</code> (draft) and <code>XOAUTH2</code> (Google). See <a href="/2.4.5/auth/scram.html">SCRAM</a> and <a href="/2.4.5/auth/oauth2.html">OAuth 2.0</a>.</p><h2 id="message-format-and-transport" tabindex="-1">Message format and transport <a class="header-anchor" href="#message-format-and-transport" aria-label="Permalink to &quot;Message format and transport&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc5322" target="_blank" rel="noreferrer nofollow">5322</a></td><td style="text-align:left;">Internet Message Format</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2045" target="_blank" rel="noreferrer nofollow">2045</a>–<a href="https://www.rfc-editor.org/rfc/rfc2049" target="_blank" rel="noreferrer nofollow">2049</a></td><td style="text-align:left;">MIME</td><td style="text-align:left;">yes</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc2231" target="_blank" rel="noreferrer nofollow">2231</a></td><td style="text-align:left;">MIME parameter continuations</td><td style="text-align:left;">yes</td><td style="text-align:left;">parameters keep their order and spelling</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8446" target="_blank" rel="noreferrer nofollow">8446</a></td><td style="text-align:left;">TLS 1.3</td><td style="text-align:left;">yes</td><td style="text-align:left;">TLS 1.2 is the default minimum</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6066" target="_blank" rel="noreferrer nofollow">6066</a></td><td style="text-align:left;">TLS <code>server_<wbr>name</code> (SNI)</td><td style="text-align:left;">partial</td><td style="text-align:left;">the name picks between <code>ssl_<wbr>server_<wbr>cert_<wbr>file</code> and <code>ssl_<wbr>server_<wbr>alt_<wbr>cert_<wbr>file</code>, by the names each covers; there are no certificates per name. The policy server gets it as <code>%{local_<wbr>name}</code></td></tr></tbody></table><p>Also spoken: the HAProxy PROXY protocol on any listener with <code>haproxy_<wbr>protocol</code>, and the Postfix policy delegation protocol in <code>yarilo-quota-status</code>. Behind a PROXY header, the client it names is the connection&#39;s remote address, and the proxy itself is what the policy server gets as <code>%{real_<wbr>remote_<wbr>ip}</code> and <code>%{real_<wbr>remote_<wbr>port}</code>.</p><h2 id="policy-server" tabindex="-1">Policy server <a class="header-anchor" href="#policy-server" aria-label="Permalink to &quot;Policy server&quot;">​</a></h2><p><code>yarilo-auth</code> calls an HTTP <a href="/2.4.5/auth/policy.html">policy server</a> before and after each login.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9110" target="_blank" rel="noreferrer nofollow">9110</a></td><td style="text-align:left;">HTTP semantics</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>POST</code>, over HTTP/1.1 or, through TLS, HTTP/2</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc8259" target="_blank" rel="noreferrer nofollow">8259</a></td><td style="text-align:left;">JSON</td><td style="text-align:left;">yes</td><td style="text-align:left;">the request body and the answer</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc7617" target="_blank" rel="noreferrer nofollow">7617</a></td><td style="text-align:left;">Basic authentication</td><td style="text-align:left;">partial</td><td style="text-align:left;"><code>auth_<wbr>policy_<wbr>server_<wbr>api_<wbr>header</code> is sent as written, so <code>Authorization: Basic …</code> works; yarilo does not encode it</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc9562" target="_blank" rel="noreferrer nofollow">9562</a></td><td style="text-align:left;">UUID</td><td style="text-align:left;">yes</td><td style="text-align:left;">version 4, from <code>%{generate:uuid}</code> in a request template</td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc4648" target="_blank" rel="noreferrer nofollow">4648</a></td><td style="text-align:left;">Base64, base64url and base16</td><td style="text-align:left;">yes</td><td style="text-align:left;">the <code>base64</code> and <code>unbase64</code> template filters, <code>url=1</code> for the URL alphabet and <code>pad=0</code> without padding; <code>hexlify</code> and <code>unhexlify</code> for base16</td></tr></tbody></table><h2 id="client-autoconfiguration" tabindex="-1">Client autoconfiguration <a class="header-anchor" href="#client-autoconfiguration" aria-label="Permalink to &quot;Client autoconfiguration&quot;">​</a></h2><p>Served by <a href="/2.4.5/installation/autoconfig.html"><code>yarilo-autoconfig</code></a>, a separate service, and by the DNS records each mail domain publishes.</p><table tabindex="0"><thead><tr><th style="text-align:left;">RFC</th><th style="text-align:left;">Title</th><th style="text-align:left;">State</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6186" target="_blank" rel="noreferrer nofollow">6186</a></td><td style="text-align:left;">SRV records for email submission and access</td><td style="text-align:left;">yes</td><td style="text-align:left;"><code>_<wbr>imaps.<wbr>_<wbr>tcp</code>, <code>_<wbr>submissions.<wbr>_<wbr>tcp</code> and <code>_<wbr>submission.<wbr>_<wbr>tcp</code>, implicit TLS preferred; see <a href="/2.4.5/installation/dns.html">DNS</a></td></tr><tr><td style="text-align:left;"><a href="https://www.rfc-editor.org/rfc/rfc6764" target="_blank" rel="noreferrer nofollow">6764</a></td><td style="text-align:left;">Locating CalDAV and CardDAV services</td><td style="text-align:left;">no</td><td style="text-align:left;">no CalDAV or CardDAV server yet</td></tr></tbody></table><p>Also spoken: Thunderbird autoconfig, format 1.1, and the Outlook POX Autodiscover answer with IMAP, POP3 and SMTP settings. ActiveSync Autodiscover requests get the POX error answer.</p>',42)])])}const h=e(d,[["render",o]]);export{y as __pageData,h as default};
